func (c *clientConn) ReadFrame() (hdr, data []byte, err error) {
	hdr = dirtmake.Bytes(5, 5)
	_, err = c.Read(hdr)
	if err != nil {
		return nil, nil, err
	}
	dLen := int(binary.BigEndian.Uint32(hdr[1:]))
	data = dirtmake.Bytes(dLen, dLen)
	_, err = c.Read(data)
	if err != nil {
		return nil, nil, err
	}

	// Emit frame read stats event for diagnostics
	if ri := rpcinfo.GetRPCInfo(c.s.Context()); ri != nil {
		frameInfo := &stats.FrameInfo{
			FrameType:   "DATA",      // gRPC message frame
			StreamID:    c.s.ID(),    // Get stream ID from grpc.Stream
			PayloadSize: dLen,        // Message payload size
			Flags:       hdr[0],      // Compression flag
		}
		stats.Record(ri, stats.FrameRead, frameInfo)
	}

	return hdr, data, nil
}

