// Dump returns a JSON-serializable map of connection pool state for diagnostics.
// Keys are remote addresses, values are slices of transport dump results.
// This method is panic-safe and will recover from any panics during dump.
func (p *connPool) Dump() interface{} {
	defer func() {
		if r := recover(); r != nil {
			klog.Errorf("connPool.Dump panic recovered: %v", r)
		}
	}()

	result := make(map[string]interface{})

	p.conns.Range(func(key, value interface{}) bool {
		addr, ok := key.(string)
		if !ok {
			return true
		}

		trans, ok := value.(*transports)
		if !ok {
			return true
		}

		// Collect transport information for this address
		var transportDumps []interface{}
		for i := uint32(0); i < trans.size; i++ {
			if trans.cliTransports[i] != nil {
				transportInfo := make(map[string]interface{})

				// Safely extract RemoteAddr
				func() {
					defer func() {
						if r := recover(); r != nil {
							klog.Errorf("Failed to get RemoteAddr for transport: %v", r)
						}
					}()
					if remoteAddr := trans.cliTransports[i].RemoteAddr(); remoteAddr != nil {
						transportInfo["remote_addr"] = remoteAddr.String()
					}
				}()

				// Safely extract LocalAddr
				func() {
					defer func() {
						if r := recover(); r != nil {
							klog.Errorf("Failed to get LocalAddr for transport: %v", r)
						}
					}()
					if localAddr := trans.cliTransports[i].LocalAddr(); localAddr != nil {
						transportInfo["local_addr"] = localAddr.String()
					}
				}()

				// Check if transport is active
				func() {
					defer func() {
						if r := recover(); r != nil {
							klog.Errorf("Failed to check IsActive for transport: %v", r)
						}
					}()
					if active, ok := trans.cliTransports[i].(grpc.IsActive); ok {
						transportInfo["is_active"] = active.IsActive()
					}
				}()

				transportDumps = append(transportDumps, transportInfo)
			}
		}

		result[addr] = transportDumps
		return true
	})

	return result
}

